namespace gui_forms {

// ToolStrip's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/tool_strip.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// Whether the grip is shown at the strip's start (Windows Forms' GripStyle; default true).
template <typename Declaring>
struct ToolStripGripVisibleCapability {
    PropertyCell<bool, ToolStripGripVisibleCapability<Declaring>> grip_visible{true};

    static void assign(ToolStripGripVisibleCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.grip_visible), incoming);
        if (!capability.grip_visible.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.grip_visible));
    }
};

// Whether the strip takes part in merging, as source or target (Windows Forms' AllowMerge; merge_strips). On by default.
template <typename Declaring>
struct ToolStripAllowMergeCapability {
    PropertyCell<bool, ToolStripAllowMergeCapability<Declaring>> allow_merge{true};

    static void assign(ToolStripAllowMergeCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.allow_merge), incoming);
        if (!capability.allow_merge.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.allow_merge));
    }
};

// Horizontal strips run left to right; vertical strips run top to bottom and are as wide as their widest item. A StatusStrip stays horizontal and throws std::logic_error when set vertical; an unknown orientation throws std::invalid_argument.
template <typename Declaring>
struct ToolStripOrientationCapability {
    PropertyCell<Orientation, ToolStripOrientationCapability<Declaring>> orientation{Orientation::horizontal};

    static void assign(ToolStripOrientationCapability& capability, Orientation incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.orientation), incoming);
        if (!capability.orientation.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.orientation));
    }
};

// Whether a sizing grip is drawn at the strip's far end (StatusStrip's SizingGrip; default false).
template <typename Declaring>
struct ToolStripSizingGripVisibleCapability {
    PropertyCell<bool, ToolStripSizingGripVisibleCapability<Declaring>> sizing_grip_visible{};

    static void assign(ToolStripSizingGripVisibleCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.sizing_grip_visible), incoming);
        if (!capability.sizing_grip_visible.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.sizing_grip_visible));
    }
};

// For QuickAccessToolbar: logical units kept free at the strip's far end for a part the derived control paints there (its customize button); items and the overflow button sit before it. Zero by default. A width that is negative, not finite or over 64 throws std::invalid_argument.
template <typename Declaring>
struct ToolStripEndReserveCapability {
    PropertyCell<double, ToolStripEndReserveCapability<Declaring>> end_reserve{0.0};

    static void assign(ToolStripEndReserveCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.end_reserve), incoming);
        if (!capability.end_reserve.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.end_reserve));
    }
};

// Every ToolStrip capability, in the order the declaring class takes them.
template <typename Declaring>
struct ToolStripCapabilities : public ToolStripGripVisibleCapability<Declaring>,
                               public ToolStripAllowMergeCapability<Declaring>,
                               public FontCapability<Declaring>,
                               public ToolStripOrientationCapability<Declaring>,
                               public ToolStripSizingGripVisibleCapability<Declaring>,
                               public ToolStripEndReserveCapability<Declaring> {
    ToolStripCapabilities() : FontCapability<Declaring>(FontSpec{FontRole::control, 10.5, 400, false, 0.12}) {}
};

} // namespace gui_forms
